struct hardware {volatile uint32_t *reg[4];};
static uint64_t time_us(void *opaque)
{(void)opaque;struct timespec t;if(clock_gettime(CLOCK_MONOTONIC,&t)||t.tv_sec<0)return 0;return (uint64_t)t.tv_sec*1000000u+(unsigned)t.tv_nsec/1000u;}
static void pause_us(void *opaque,uint32_t us)
{(void)opaque;struct timespec t={us/1000000,(us%1000000)*1000L};while(nanosleep(&t,&t)<0&&errno==EINTR);}
static uint32_t read_hw(void *opaque,unsigned r,uint32_t off)
{struct hardware *h=opaque;return h->reg[r][off/4];}
static int write_hw(void *opaque,unsigned r,uint32_t off,uint32_t value)
{
    struct hardware *h=opaque;
    int valid=(r==QA_CPM&&(off==0x20||off==0x70||off==0x84))||
        (r==QA_AIC&&(off==0||off==4||off==0x10||off==0x14||off==0x30))||
        (r==QA_CODEC&&off<=0x130&&!(off&3))||
        (r==QA_PDMA&&(off==5*32+0x10||off==6*32+0x10||off==QA_CH+0xc||off==QA_CH+8||off==QA_CH+0x10||off==QA_CH+0x18||off==0x1000||off==0x100c));
    if(!valid)return 0;
    __sync_synchronize();h->reg[r][off/4]=value;__sync_synchronize();return 1;
}
static int video_mode(int fd,int concurrent)
{
    static const unsigned offs[]={0xd040,0x800,0xb0,0x1060,0x7804};
    const volatile uint32_t *isp=mmap(0,0x10000,PROT_READ,MAP_SHARED,fd,0x13300000);
    const volatile uint32_t *vic=mmap(0,4096,PROT_READ,MAP_SHARED,fd,0x133e0000);
    if(isp==MAP_FAILED||vic==MAP_FAILED){if(isp!=MAP_FAILED)munmap((void *)isp,0x10000);if(vic!=MAP_FAILED)munmap((void *)vic,4096);return 0;}
    int ok=isp[0xd040/4]==(concurrent?1u:0u);
    if(!concurrent)for(unsigned n=1;n<sizeof offs/sizeof *offs;n++)ok&=(isp[offs[n]/4]&(n<3?0xffffffffu:1u))==0;
    ok&=vic[0x300/4]==0&&vic[0x308/4]==0;
    munmap((void *)isp,0x10000);munmap((void *)vic,4096);return ok;
}
